<?php
require dirname(__DIR__).'/app/bootstrap.php';
$me=require_login();
$canManage=can('pitch.review')&&can('assignment.manage');
$canPitch=can('pitch.create');
$canWork=can('assignment.work');
$canAssignments=$canManage||$canPitch||$canWork;
if(!$canAssignments){http_response_code(403);exit('Newsroom operations permission required.');}
$view=(string)($_GET['view']??'pitches');
if(!in_array($view,['pitches','assignments','calendar'],true))$view='pitches';
$error='';

function newsroom_redirect(string $view): never {header('Location: '.path('admin/newsroom-operations.php?view='.rawurlencode($view)));exit;}
function newsroom_notify(int $userId,string $type,string $title,string $body,string $entity,int $entityId): void {
    db()->prepare('INSERT INTO notifications(user_id,notification_type,title,body,entity_type,entity_id) VALUES (?,?,?,?,?,?)')->execute([$userId,$type,substr($title,0,240),substr($body,0,1000),$entity,$entityId]);
}

if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();$action=(string)($_POST['action']??'');
 try{
  if($action==='create_pitch'){
   if(!$canPitch)throw new RuntimeException('Your role cannot submit story pitches.');
   $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$angle=trim((string)($_POST['proposed_angle']??''));$sourcePlan=trim((string)($_POST['source_plan']??''));
   $urgency=(string)($_POST['urgency']??'normal');$risk=(string)($_POST['risk_level']??'standard');$cost=max(0,(int)($_POST['expected_cost_minor']??0));$deadline=trim((string)($_POST['deadline']??''));
   if(mb_strlen($title)<10||mb_strlen($title)>240||mb_strlen($description)<20)throw new RuntimeException('Pitch title (10+) and description (20+) are required.');
   if(!in_array($urgency,['low','normal','high','breaking'],true)||!in_array($risk,['low','standard','high','critical'],true))throw new RuntimeException('Invalid urgency or risk.');
   if($deadline!==''&&strtotime($deadline)===false)throw new RuntimeException('Invalid deadline.');
   db()->prepare('INSERT INTO story_pitches(title,description,proposed_angle,source_plan,urgency,expected_cost_minor,currency,risk_level,reporting_location,proposed_by,deadline) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$title,$description,substr($angle,0,10000)?:null,substr($sourcePlan,0,10000)?:null,$urgency,$cost,'RWF',$risk,substr(trim((string)($_POST['reporting_location']??'')),0,190)?:null,(int)$me['id'],$deadline!==''?date('Y-m-d H:i:s',strtotime($deadline)):null]);
   $id=(int)db()->lastInsertId();audit_log('pitch_submitted','story_pitch',$id,$urgency);flash('Story pitch submitted to the news desk.');newsroom_redirect('pitches');
  }
  if($action==='resubmit_pitch'){
   if(!$canPitch)throw new RuntimeException('Your role cannot resubmit pitches.');$id=(int)($_POST['id']??0);$pitch=query_one('SELECT * FROM story_pitches WHERE id=?',[$id]);
   if(!$pitch||(int)$pitch['proposed_by']!==(int)$me['id']||!in_array($pitch['status'],['clarification','hold'],true))throw new RuntimeException('Only the proposer can resubmit a pitch awaiting clarification or on hold.');
   $description=trim((string)($_POST['description']??''));$angle=trim((string)($_POST['proposed_angle']??''));if(mb_strlen($description)<20)throw new RuntimeException('Updated description must be at least 20 characters.');
   $s=db()->prepare("UPDATE story_pitches SET description=?,proposed_angle=?,status='submitted',decision_reason=NULL,decided_by=NULL,lock_version=lock_version+1 WHERE id=? AND lock_version=?");$s->execute([$description,substr($angle,0,10000)?:null,$id,(int)$pitch['lock_version']]);if($s->rowCount()!==1)throw new RuntimeException('Pitch changed concurrently. Reload and try again.');
   audit_log('pitch_resubmitted','story_pitch',$id);flash('Pitch returned to the news desk.');newsroom_redirect('pitches');
  }
  if($action==='decide_pitch'){
   if(!$canManage)throw new RuntimeException('News desk review permission required.');$id=(int)($_POST['id']??0);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['reason']??''));$pitch=query_one('SELECT * FROM story_pitches WHERE id=?',[$id]);
   if(!$pitch||!in_array($pitch['status'],['submitted','clarification','hold'],true))throw new RuntimeException('Pitch is not awaiting a desk decision.');if(!in_array($decision,['accepted','rejected','clarification','hold','merged'],true))throw new RuntimeException('Invalid decision.');if(mb_strlen($reason)<10)throw new RuntimeException('A decision reason of at least 10 characters is required.');
   $mergedInto=null;if($decision==='merged'){$mergedInto=(int)($_POST['merged_into_id']??0);if($mergedInto<1||$mergedInto===$id||!query_one('SELECT id FROM story_pitches WHERE id=?',[$mergedInto]))throw new RuntimeException('A valid different pitch is required for merge.');}
   $s=db()->prepare('UPDATE story_pitches SET status=?,decision_reason=?,decided_by=?,merged_into_id=?,lock_version=lock_version+1 WHERE id=? AND lock_version=?');$s->execute([$decision,substr($reason,0,1000),(int)$me['id'],$mergedInto,$id,(int)$pitch['lock_version']]);if($s->rowCount()!==1)throw new RuntimeException('Pitch changed concurrently. Reload and try again.');
   newsroom_notify((int)$pitch['proposed_by'],'pitch_decision','Story pitch: '.ucfirst($decision),$reason,'story_pitch',$id);audit_log('pitch_decision','story_pitch',$id,$decision);flash('Pitch decision recorded and proposer notified.');newsroom_redirect('pitches');
  }
  if($action==='assign_pitch'){
   if(!$canManage)throw new RuntimeException('News desk assignment permission required.');$pitchId=(int)($_POST['pitch_id']??0);$assignee=(int)($_POST['assigned_to']??0);$priority=(string)($_POST['priority']??'normal');$due=trim((string)($_POST['due_at']??''));$briefing=trim((string)($_POST['briefing']??''));$articleId=(int)($_POST['article_id']??0);
   $pitch=query_one('SELECT * FROM story_pitches WHERE id=?',[$pitchId]);$user=query_one('SELECT id,full_name,role FROM users WHERE id=? AND active=1',[$assignee]);$eligibleRoles=['reporter','investigative_reporter','external_contributor'];$userRoles=$user?load_user_roles($assignee,(string)$user['role']):[];if(!$pitch||$pitch['status']!=='accepted'||!$user||!array_intersect($eligibleRoles,$userRoles))throw new RuntimeException('Accepted pitch and an active reporting-role assignee are required.');if(!in_array($priority,['low','normal','high','urgent'],true)||$due===''||strtotime($due)===false||strtotime($due)<=time())throw new RuntimeException('Valid priority and future due date are required.');if(mb_strlen($briefing)<10)throw new RuntimeException('Assignment briefing must be at least 10 characters.');
   if($articleId>0&&!query_one('SELECT id FROM articles WHERE id=?',[$articleId]))throw new RuntimeException('Linked article does not exist.');
   db()->beginTransaction();try{db()->prepare("INSERT INTO editorial_assignments(article_id,pitch_id,assigned_to,assignment_type,priority,briefing,status,due_at,assigned_by) VALUES (?,?,?,'reporting',?,?,'assigned',?,?)")->execute([$articleId?:null,$pitchId,$assignee,$priority,substr($briefing,0,10000),date('Y-m-d H:i:s',strtotime($due)),(int)$me['id']]);$assignmentId=(int)db()->lastInsertId();$s=db()->prepare("UPDATE story_pitches SET status='assigned',assigned_to=?,deadline=?,lock_version=lock_version+1 WHERE id=? AND status='accepted' AND lock_version=?");$s->execute([$assignee,date('Y-m-d H:i:s',strtotime($due)),$pitchId,(int)$pitch['lock_version']]);if($s->rowCount()!==1)throw new RuntimeException('Pitch changed concurrently. Reload and try again.');newsroom_notify($assignee,'editorial_assignment','New editorial assignment',$pitch['title'].' — due '.date('Y-m-d H:i',strtotime($due)),'editorial_assignment',$assignmentId);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
   audit_log('assignment_created','editorial_assignment',$assignmentId,'pitch:'.$pitchId);flash('Assignment created and assignee notified.');newsroom_redirect('assignments');
  }
  if($action==='update_assignment'){
   $id=(int)($_POST['id']??0);$to=(string)($_POST['status']??'');$assignment=query_one('SELECT * FROM editorial_assignments WHERE id=?',[$id]);if(!$assignment||(!$canManage&&(!$canWork||(int)$assignment['assigned_to']!==(int)$me['id'])))throw new RuntimeException('Assignment not found or not assigned to you.');
   $from=(string)$assignment['status'];$allowed=['assigned'=>['in_progress','cancelled'],'in_progress'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];if(!in_array($to,$allowed[$from]??[],true))throw new RuntimeException('Invalid assignment transition.');if($to==='cancelled'&&!$canManage)throw new RuntimeException('Only the news desk can cancel assignments.');
   $started=$to==='in_progress'?date('Y-m-d H:i:s'):($assignment['started_at']??null);$completed=$to==='completed'?date('Y-m-d H:i:s'):null;$s=db()->prepare('UPDATE editorial_assignments SET status=?,started_at=?,completed_at=?,updated_at='.sql_now().' WHERE id=? AND status=?');$s->execute([$to,$started,$completed,$id,$from]);if($s->rowCount()!==1)throw new RuntimeException('Assignment changed concurrently. Reload and try again.');
   audit_log('assignment_status','editorial_assignment',$id,$from.'>'.$to);flash('Assignment status updated.');newsroom_redirect('assignments');
  }
  throw new RuntimeException('Unknown newsroom operation.');
 }catch(Throwable $e){$error=$e->getMessage();}
}

$scopeSql=$canManage?'1=1':'(p.proposed_by='.(int)$me['id'].' OR p.assigned_to='.(int)$me['id'].')';
$pitches=query_all("SELECT p.*,proposer.full_name proposer_name,assignee.full_name assignee_name,decider.full_name decider_name FROM story_pitches p JOIN users proposer ON proposer.id=p.proposed_by LEFT JOIN users assignee ON assignee.id=p.assigned_to LEFT JOIN users decider ON decider.id=p.decided_by WHERE $scopeSql ORDER BY CASE p.urgency WHEN 'breaking' THEN 1 WHEN 'high' THEN 2 WHEN 'normal' THEN 3 ELSE 4 END,p.created_at DESC LIMIT 200");
$assignmentWhere=$canManage?'1=1':'ea.assigned_to='.(int)$me['id'];
$assignments=query_all("SELECT ea.*,p.title pitch_title,a.title article_title,u.full_name assignee_name,manager.full_name assigned_by_name FROM editorial_assignments ea LEFT JOIN story_pitches p ON p.id=ea.pitch_id LEFT JOIN articles a ON a.id=ea.article_id JOIN users u ON u.id=ea.assigned_to JOIN users manager ON manager.id=ea.assigned_by WHERE $assignmentWhere ORDER BY CASE ea.status WHEN 'in_progress' THEN 1 WHEN 'assigned' THEN 2 ELSE 3 END,ea.due_at LIMIT 250");
$staff=$canManage?array_values(array_filter(query_all('SELECT id,full_name,role FROM users WHERE active=1 ORDER BY full_name'),fn(array $u):bool=>(bool)array_intersect(['reporter','investigative_reporter','external_contributor'],load_user_roles((int)$u['id'],(string)$u['role'])))):[];
$accepted=$canManage?array_values(array_filter($pitches,fn(array $p):bool=>$p['status']==='accepted')):[];
$calendarAssignments=$view==='calendar'?query_all("SELECT ea.id,ea.due_at,ea.status,ea.priority,p.title pitch_title,u.full_name assignee_name FROM editorial_assignments ea LEFT JOIN story_pitches p ON p.id=ea.pitch_id JOIN users u ON u.id=ea.assigned_to WHERE $assignmentWhere AND ea.due_at IS NOT NULL AND ea.status IN ('assigned','in_progress') ORDER BY ea.due_at LIMIT 200"):[];
$scheduled=$view==='calendar'&&$canManage?query_all("SELECT id,title,scheduled_at,status FROM articles WHERE scheduled_at IS NOT NULL AND status IN ('approved','scheduled') ORDER BY scheduled_at LIMIT 200"):[];
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Newsroom Operations · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"><style>.ops-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px}.ops-card{border:1px solid #dbe0db;background:#fff;padding:22px}.ops-card h3{margin-top:0}.ops-meta{color:#65736f;font-size:12px}.ops-actions{display:flex;flex-wrap:wrap;gap:8px}.ops-actions form{min-width:210px;flex:1}.risk-critical,.urgency-breaking{color:#a51f18;font-weight:800}.calendar-row{display:grid;grid-template-columns:170px 1fr 150px;gap:15px;border-bottom:1px solid #e2e5e1;padding:13px 0}@media(max-width:700px){.calendar-row{grid-template-columns:1fr}}</style></head><body class="admin-body"><main class="admin-content" style="max-width:1300px;margin:auto"><p><a href="<?=e(path('admin/index.php'))?>">← Newsroom</a></p><div class="admin-section-title"><h1>Newsroom Operations<span class="brand-accent">.</span></h1></div><nav class="admin-menu" style="display:flex;flex-direction:row;flex-wrap:wrap;margin-bottom:25px"><a class="<?=$view==='pitches'?'active':''?>" href="?view=pitches">Story Pitches</a><a class="<?=$view==='assignments'?'active':''?>" href="?view=assignments">Assignments</a><a class="<?=$view==='calendar'?'active':''?>" href="?view=calendar">Editorial Calendar</a></nav><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($msg=notice()):?><div class="admin-notice"><?=e($msg)?></div><?php endif;?>

<?php if($view==='pitches'):?>
 <?php if($canPitch):?><section class="setting-panel"><h2>Submit a story pitch</h2><p>Describe a source plan, not confidential identities. Store protected identities only in the encrypted article source fields.</p><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="create_pitch"><label>WORKING TITLE<input name="title" minlength="10" maxlength="240" required></label><label>DESCRIPTION<textarea name="description" minlength="20" required></textarea></label><label>PROPOSED ANGLE<textarea name="proposed_angle"></textarea></label><label>SOURCE PLAN — NO IDENTITIES<textarea name="source_plan"></textarea></label><label>URGENCY<select name="urgency"><option>low</option><option selected>normal</option><option>high</option><option>breaking</option></select></label><label>RISK<select name="risk_level"><option>low</option><option selected>standard</option><option>high</option><option>critical</option></select></label><label>REPORTING LOCATION<input name="reporting_location" maxlength="190"></label><label>EXPECTED COST (RWF, WHOLE AMOUNT)<input type="number" name="expected_cost_minor" min="0" step="1" value="0"></label><label>PROPOSED DEADLINE<input type="datetime-local" name="deadline"></label><button>SUBMIT PITCH →</button></form></section><?php endif;?>
 <div class="ops-grid"><?php foreach($pitches as $p):?><article class="ops-card"><p class="ops-meta"><?=e(display_date($p['created_at']))?> · <?=e($p['proposer_name'])?></p><h3><?=e($p['title'])?></h3><p><?=nl2br(e($p['description']))?></p><p><b>Status:</b> <?=e($p['status'])?> · <span class="urgency-<?=e($p['urgency'])?>"><?=e($p['urgency'])?></span> · <span class="risk-<?=e($p['risk_level'])?>"><?=e($p['risk_level'])?> risk</span></p><?php if($p['decision_reason']):?><p><b>Desk decision:</b> <?=e($p['decision_reason'])?></p><?php endif;?><?php if($p['assignee_name']):?><p><b>Assigned:</b> <?=e($p['assignee_name'])?></p><?php endif;?>
 <?php if(!$canManage&&(int)$p['proposed_by']===(int)$me['id']&&in_array($p['status'],['clarification','hold'],true)):?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="resubmit_pitch"><input type="hidden" name="id" value="<?=$p['id']?>"><label>UPDATED DESCRIPTION<textarea name="description" minlength="20" required><?=e($p['description'])?></textarea></label><label>UPDATED ANGLE<textarea name="proposed_angle"><?=e($p['proposed_angle']??'')?></textarea></label><button>RESUBMIT →</button></form><?php endif;?>
 <?php if($canManage&&in_array($p['status'],['submitted','clarification','hold'],true)):?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="decide_pitch"><input type="hidden" name="id" value="<?=$p['id']?>"><label>DECISION<select name="decision"><option value="accepted">Accept</option><option value="clarification">Request clarification</option><option value="hold">Hold</option><option value="rejected">Reject</option><option value="merged">Merge</option></select></label><label>REASON<input name="reason" minlength="10" required></label><label>MERGE INTO PITCH ID<input type="number" min="1" name="merged_into_id"></label><button>RECORD DECISION</button></form><?php endif;?></article><?php endforeach;?></div>

<?php elseif($view==='assignments'):?>
 <?php if($canManage):?><section class="setting-panel"><h2>Assign an accepted pitch</h2><?php if(!$accepted):?><p>No accepted unassigned pitch is available.</p><?php else:?><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="assign_pitch"><label>PITCH<select name="pitch_id"><?php foreach($accepted as $p):?><option value="<?=$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></select></label><label>ASSIGNEE<select name="assigned_to"><?php foreach($staff as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'].' · '.$u['role'])?></option><?php endforeach;?></select></label><label>PRIORITY<select name="priority"><option>low</option><option selected>normal</option><option>high</option><option>urgent</option></select></label><label>DUE AT<input type="datetime-local" name="due_at" required></label><label>BRIEFING<textarea name="briefing" minlength="10" required></textarea></label><label>EXISTING ARTICLE ID (OPTIONAL)<input type="number" name="article_id" min="1"></label><button>CREATE ASSIGNMENT →</button></form><?php endif;?></section><?php endif;?>
 <div class="ops-grid"><?php foreach($assignments as $a):?><article class="ops-card"><p class="ops-meta">Due <?=e(display_date($a['due_at']))?> · <?=e($a['priority'])?> priority</p><h3><?=e($a['pitch_title']??$a['article_title']??('Assignment #'.$a['id']))?></h3><p><?=nl2br(e($a['briefing']??''))?></p><p><b>Assignee:</b> <?=e($a['assignee_name'])?><br><b>Status:</b> <?=e($a['status'])?><br><b>Assigned by:</b> <?=e($a['assigned_by_name'])?></p><?php if(in_array($a['status'],['assigned','in_progress'],true)&&($canManage||(int)$a['assigned_to']===(int)$me['id'])):?><div class="ops-actions"><?php if($a['status']==='assigned'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update_assignment"><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="in_progress"><button>START WORK</button></form><?php endif;?><?php if($a['status']==='in_progress'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update_assignment"><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="completed"><button>MARK COMPLETE</button></form><?php endif;?><?php if($canManage):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update_assignment"><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="cancelled"><button>CANCEL</button></form><?php endif;?></div><?php endif;?></article><?php endforeach;?></div>

<?php else:?><section class="setting-panel"><h2>Deadlines and scheduled publications</h2><p>Times are shown in the configured newsroom timezone. This calendar uses persisted assignments and scheduled articles only.</p><?php foreach($calendarAssignments as $item):?><div class="calendar-row"><b><?=e(display_date($item['due_at']))?></b><span><?=e($item['pitch_title']??('Assignment #'.$item['id']))?> · <?=e($item['assignee_name'])?></span><span><?=e($item['priority'].' / '.$item['status'])?></span></div><?php endforeach;?><?php if($canManage):?><?php foreach($scheduled as $article):?><div class="calendar-row"><b><?=e(display_date($article['scheduled_at']))?></b><a href="<?=e(path('admin/index.php?page=edit&id='.$article['id']))?>"><?=e($article['title'])?></a><span><?=e($article['status'])?></span></div><?php endforeach;?><?php endif;?></section><?php endif;?>
</main></body></html>
